function migrate(value) {
  const s = copy(value);
  if (s?.schemaVersion === 1 && s.contentVersion === 'phase1.1') {
    s.contentVersion = CONTENT; s.trip.earnedCents = s.trip.earnedCents || 0;
    // Old active diners finish using their original nodes and saved RNG.
  }
  validate(s); return s;
}

function upgradeJourney(value) {
  const next = clone(value);
  if (next?.story) next.story = E.migrate(next.story);
  validateSaved(next); return next;
}
function callbackDue(j) {
  const q=j.story?.world.flags.partsJob;
  return !j.currentEvent && !j.ended && !!q && !q.callbackDone && ['repaired','referred','botched'].includes(q.status) && j.distance >= q.dueAtMiles;
}
function discoveryEligible(j) {
  if (j.distance <= 60) return false;
  const key=String(j.car?.id)+':'+String(j.car?.boughtPrice||0);
  return !j.story?.world.flags.carSearches?.[key]?.claimed;
}

const v = active ? B.describe(s.story) : null;
$('roadScreen').classList.toggle('story-indoor',v?.presentation==='diner');
place.render(v);

function say(speaker, text) {
  if(!ctx||!bus||ctx.state!=='running')return;
  let hash=0;for(const ch of speaker)hash=(hash*31+ch.charCodeAt(0))>>>0;
  const base=105+(hash%105),count=Math.min(10,Math.max(3,Math.ceil(text.length/18)));
  for(let i=0;i<count;i++)tone(base+(i%3)*12,.15+(i%2)*.03,.018,i*.21,true);
}
function speakLines(lines){
  clearVoices();let delay=0;
  for(const line of lines.filter(l=>!['SCENE','SOUND','YOU'].includes(l.speaker)).slice(0,4)){
    queued.push(setTimeout(()=>say(line.speaker,line.text),delay));delay+=Math.min(10,Math.max(3,Math.ceil(line.text.length/18)))*210+300;
  }
}

